const redisItems = $input.all();
const sourceItems = $('Распаковать кэш').all();
const newArticles = [];

for (let i = 0; i < redisItems.length; i++) {
  const redisVal = redisItems[i].json.propertyName;
  const isNew = redisVal === null || redisVal === undefined || redisVal === '';
  if (isNew && sourceItems[i]) {
    newArticles.push({ json: sourceItems[i].json });
  }
}

if (newArticles.length === 0) {
  return [{ json: { isEmpty: true, forLLM: '', total: 0 } }];
}

return newArticles;

let history = [];
try {
  const raw = $('Redis: Читать историю').first().json.propertyName
           || $('Redis: Читать историю').first().json.value || '';
  if (raw) history = JSON.parse(raw);
} catch(e) {
  history = [];
}

const last3 = history.slice(0, 3);

let historyBlock = '';
if (last3.length > 0) {
  historyBlock = '\n\n---\nПРЕДЫДУЩИЕ СЮЖЕТЫ (последние ' + last3.length + ' выпуска, от нового к старому):\n';
  last3.forEach((s, i) => {
    historyBlock += '<entry ' + (i+1) + '>\nДата: ' + s.date + '\n';
    if (s.military)     historyBlock += 'Военные: ' + s.military + '\n';
    if (s.hydrocarbons) historyBlock += 'Углеводороды: ' + s.hydrocarbons + '\n';
    historyBlock += '</entry ' + (i+1) + '>\n';
  });
  historyBlock += '---';
}

const items = $('Предфильтр по теме').all();
const validItems = items.filter(i => !i.json.isEmpty);

if (validItems.length === 0) {
  return [{ json: {
    isEmpty: true,
    forLLM: '',
    total: 0,
    historyBlock: '',
    rawHistory: JSON.stringify(history),
    refMap: '{}'
  } }];
}

// Нумеруем статьи. LLM видит только [N] [Источник] Заголовок — без URL.
// URL хранится в refMap и восстанавливается после ответа LLM.
const lines = [];
const refMap = {};

validItems.forEach((item, idx) => {
  const num = String(idx + 1);
  lines.push('[' + num + '] [' + item.json.source + '] ' + item.json.title);
  refMap[num] = { url: item.json.link, source: item.json.source };
});

return [{ json: {
  isEmpty: false,
  forLLM: lines.join('\n'),
  total: lines.length,
  historyBlock,
  rawHistory: JSON.stringify(history),
  refMap: JSON.stringify(refMap)
} }];

// Парсим ответ LLM (полный текст до разбивки)
const fullText = $json.text || '';

const memMatch = fullText.match(/%%STORY_MEMORY%%([\s\S]*?)(?:%%END%%|%%STORY_MEMORY%%|$)/);
let military = null;
let hydrocarbons = null;

if (memMatch) {
  const memBlock = memMatch[1];
  const milMatch = memBlock.match(/MILITARY:\s*(.+)/);
  const hydroMatch = memBlock.match(/HYDROCARBONS:\s*(.+)/);
  military = milMatch ? milMatch[1].trim() : null;
  hydrocarbons = hydroMatch ? hydroMatch[1].trim() : null;
  if (military === 'NONE') military = null;
  if (hydrocarbons === 'NONE') hydrocarbons = null;
}

const cleanText = fullText.replace(/%%STORY_MEMORY%%[\s\S]*/g, '').trim();
const displayText = cleanText === 'NONE' ? 'Новых новостей нет. Может, оно и к лучшему!' : cleanText;
// Собираем историю для Redis
let history = [];
try {
  const raw = $('Сборка в текст').first().json.rawHistory || '[]';
  history = JSON.parse(raw);
} catch(e) {
  history = [];
}

if (military || hydrocarbons) {
  const now = new Date();
  const dateStr = now.toLocaleDateString('ru-RU', {
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  });

  history.unshift({
    date: dateStr,
    military: military || null,
    hydrocarbons: hydrocarbons || null
  });

  if (history.length > 20) history = history.slice(0, 20);
}

// Добавляем котировки
let quotesBlock = '';
try {
  quotesBlock = $('Котировки').first().json.quotesBlock || '';
} catch(e) {}

const finalText = displayText + quotesBlock;

return [{ json: {
  text: finalText,
  newHistory: JSON.stringify(history),
  hasUpdate: !!(military || hydrocarbons)
} }];

const keywords = {
  core: [
    'iran', 'иран', 'tehran', 'тегеран', 'irgc', 'ксир', 'khamenei', 'хаменеи',
    'hormuz', 'ормуз', 'persian gulf', 'персидский залив', 'gulf', 'залив',
    'strait of hormuz', 'middle east', 'ближний восток'
  ],
  regional: [
    'saudi', 'сауд', 'riyadh', 'эр-рияд', 'aramco', 'uae', 'оаэ', 'abu dhabi', 'абу-даби',
    'dubai', 'дубай', 'qatar', 'катар', 'bahrain', 'бахрейн', 'kuwait', 'кувейт',
    'oman', 'оман', 'yemen', 'йемен', 'houthi', 'хусит', 'hezbollah', 'хезболл', 'lebanon', 'ливан'
  ],
  energy: [
    'oil', 'нефт', 'brent', 'wti', 'crude', 'lng', 'спг', 'gas', 'газ',
    'tanker', 'танкер', 'opec', 'опек', 'refinery', 'нпз', 'shipping', 'морские поставки'
  ],
  military: [
    'missile', 'ракет', 'drone', 'дрон', 'беспилот', 'intercept', 'перехват',
    'air defense', 'пво', 'strike', 'удар', 'airstrike', 'авиаудар',
    'warship', 'военный корабль', 'submarine', 'подлод', 'navy', 'флот'
  ]
};

const items = $('Фильтр: только новые').all();
const filtered = [];

const scoreText = (text) => {
  const t = String(text || '').toLowerCase();
  let score = 0;

  for (const kw of keywords.core) if (t.includes(kw)) score += 4;
  for (const kw of keywords.regional) if (t.includes(kw)) score += 2;
  for (const kw of keywords.energy) if (t.includes(kw)) score += 2;
  for (const kw of keywords.military) if (t.includes(kw)) score += 2;

  return score;
};

for (const item of items) {
  if (item.json.isEmpty) continue;

  const title = item.json.title || '';
  const source = item.json.source || '';
  const description = item.json.description || '';

  let score = 0;
  score += scoreText(title) * 2;
  score += scoreText(description);
  score += scoreText(source);

  const titleLc = title.toLowerCase();

  const hardAllow = /\b(iran|tehran|irgc|khamenei|hormuz|оаэ|qatar|kuwait|bahrain|aramco|brent|wti|opec|houthi|hezbollah|иран|тегеран|ксир|ормуз|залив)\b/i.test(titleLc);
  const hardReject = /(soccer|football|movie|celebrity|weather|school|festival|recipes)/i.test(titleLc);

  if (hardReject) continue;
  if (hardAllow || score >= 6) filtered.push(item);
}

if (filtered.length === 0) {
  return [{ json: { isEmpty: true } }];
}

return filtered;

// Telegram лимит — 4096 символов
const MAX_LEN = 4000; // с запасом

const input = $input.first().json;
let text = input.text || input.response || '';

// === Санитизация HTML для Telegram ===

// 1. Убираем <URL> без тега a (Квен иногда так делает)
text = text.replace(/<(https?:\/\/[^>]+)>/g, '$1');

// 2. Чиним незакрытые <a> теги
const openA = (text.match(/<a\s/gi) || []).length;
const closeA = (text.match(/<\/a>/gi) || []).length;
if (openA > closeA) {
  text = text.replace(/<a\s+href="[^"]*">[^<]*$/gm, '');
}

// 3. Закрываем незакрытые <b>
const openB = (text.match(/<b>/gi) || []).length;
const closeB = (text.match(/<\/b>/gi) || []).length;
if (openB > closeB) {
  for (let i = 0; i < openB - closeB; i++) text += '</b>';
}

// 4. Убираем любые HTML-теги кроме разрешённых Telegram: b, i, a, code, pre
text = text.replace(/<\/?(?!b>|\/b>|i>|\/i>|a[\s>]|\/a>|code>|\/code>|pre>|\/pre>)[^>]+>/gi, '');

// 5. Обрезанные теги в конце
text = text.replace(/<[^>]*$/, '');

// 6. Убираем Markdown-звёздочки: **текст** → <b>текст</b>
text = text.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');

// === Разбивка на чанки ===

if (!text || text.length <= MAX_LEN) {
  return [{ json: { text, part: 1, totalParts: 1 } }];
}

const lines = text.split('\n');
const chunks = [];
let current = '';

for (const line of lines) {
  if (line.length > MAX_LEN) {
    if (current) {
      chunks.push(current);
      current = '';
    }
    chunks.push(line.substring(0, MAX_LEN));
    continue;
  }

  if ((current + '\n' + line).length > MAX_LEN) {
    chunks.push(current);
    current = line;
  } else {
    current = current ? current + '\n' + line : line;
  }
}

if (current) {
  chunks.push(current);
}

const totalParts = chunks.length;
return chunks.map((chunk, i) => ({
  json: {
    text: totalParts > 1
      ? chunk + `\n\n📄 ${i + 1}/${totalParts}`
      : chunk,
    part: i + 1,
    totalParts
  }
}));

// Ручной запуск: подставляем chatId и имя
return [{
  json: {
    message: {
      chat: { id: 796561380 },
      from: { first_name: 'Ручной запуск' },
      text: '🔄 Обновить'
    }
  }
}];

const input = $input.first().json;
let text = input.text || '';

let refMap = {};
try {
  const raw = $('Сборка в текст').first().json.refMap || '{}';
  refMap = JSON.parse(raw);
} catch(e) {}

const lines = text.split('\n');
const filtered = [];

for (const line of lines) {
  const trimmed = line.trim();

  if (!trimmed.startsWith('-')) {
    filtered.push(line);
    continue;
  }

  let skip = false;

  // === ФИЛЬТР ГАЛЛЮЦИНАЦИЙ ===
  // Если в строке есть [N] — все они должны существовать в refMap
  // Если [N] нет совсем — строка тоже подозрительна (LLM не сослался ни на что)
  if (!skip) {
    const refNums = trimmed.match(/\[(\d+)\]/g);
    if (refNums) {
      const allValid = refNums.every(r => refMap[r.replace(/[\[\]]/g, '')]);
      if (!allValid) skip = true;
    } else {
      // Нет номеров совсем — галлюцинация без ссылки, пропускаем
      skip = true;
    }
  }

  // === УДАЛЯЕМ СТРОКИ С ⚠️ — заявления одной стороны о другой ===
  if (!skip && /^-\s*⚠️/.test(trimmed)) {
    skip = true;
  }

  // === ПРОПАГАНДА (страховка если LLM забыл ⚠️) ===
  if (!skip) {
    const propagandaPatterns = [

    ];
    for (const pat of propagandaPatterns) {
      if (pat.test(trimmed)) { skip = true; break; }
    }
  }

  // === ИСТОЧНИКИ ПРОПАГАНДЫ ===
  if (!skip) {
    const isParsToday = /pars.?today|press.?tv/i.test(trimmed);
    if (isParsToday) {
      const isSelfReport = /иран.*потерял|иран.*погиб|иран.*признал|iran.*lost|iran.*killed|iran.*damage/i.test(trimmed);
      if (!isSelfReport) skip = true;
    }
  }

  // === АНАЛИТИКА И ПРОГНОЗЫ ===
  if (!skip) {
    const opinionPatterns = [
      /прогноз.*цен/i, /повышает прогноз/i, /прогнозируется/i,
      /forecast.*barrel/i, /hikes.*forecast/i,
      /could rise/i, /could help/i, /\bcould\b/i, /\bmight\b/i,
      /может вырасти/i, /могут вырасти/i, /ожидается рост/i,
      /expected.*rise/i, /tipped.*rise/i, /\boutlook\b/i,
      /по мнению/i, /эксперты полагают/i, /according to sources/i,
      /analysts say/i, /аналитики считают/i, /\banalysis\b/i,
      /узнал[аи]?\b/i, /выяснил[аи]?\b/i, /learned why/i,
    ];
    for (const pat of opinionPatterns) {
      if (pat.test(trimmed)) { skip = true; break; }
    }
  }

  // === HUMAN INTEREST / НЕКРОЛОГИ ===
  if (!skip) {
    const humanInterestPatterns = [
      /remembered as/i, /loving parents/i, /dedicated students/i,
      /made.*history/i, /one beer/i, /back on duty/i, /raf history/i,
      /still alive/i, /всё ещё жив/i, /всё еще жив/i,
    ];
    for (const pat of humanInterestPatterns) {
      if (pat.test(trimmed)) { skip = true; break; }
    }
  }

  // === ПУСТЫЕ ЗАЯВЛЕНИЯ БЕЗ ДЕЙСТВИЯ ===
  if (!skip) {
    const emptyClaimsPatterns = [
      /vows.*secure.*oil/i, /vows.*route/i, /обещает.*маршрут/i,
      /calls for restraint/i, /urges dialogue/i, /призывает к/i,
      /предупреждение о безопасности/i, /security alert/i,
    ];
    for (const pat of emptyClaimsPatterns) {
      if (pat.test(trimmed)) { skip = true; break; }
    }
  }

  // === РОССИЙСКО-УКРАИНСКИЙ ОФФТОПИК ===
  if (!skip) {
    const isRuUa = /над россией|над российскими|саратовск|украинск.*дрон|сбили.*беспилотник.*росси|российских регион/i.test(trimmed);
    const isIran = /иран|ормуз|hormuz|залив|gulf|нефт|oil|газ|lng|спг|танкер|саудовск|saudi|оаэ|uae|бахрейн|кувейт|ближн.*восток|middle east|санкц|эмбарго|дипломат|оон|совбез/i.test(trimmed);
    if (isRuUa && !isIran) skip = true;
  }

  if (!skip) filtered.push(line);
}

// Убираем пустые разделы
const sectionHeaderRe = /^\s*<b>[^<]+<\/b>\s*$/;
const cleaned = [];

for (let i = 0; i < filtered.length; i++) {
  const trimmed = filtered[i].trim();
  if (sectionHeaderRe.test(trimmed)) {
    let hasBullet = false;
    for (let j = i + 1; j < filtered.length; j++) {
      const next = filtered[j].trim();
      if (next.startsWith('-')) { hasBullet = true; break; }
      if (sectionHeaderRe.test(next)) break;
    }
    if (hasBullet) cleaned.push(filtered[i]);
  } else {
    cleaned.push(filtered[i]);
  }
}

let result = cleaned.join('\n');
result = result.replace(/\n{3,}/g, '\n\n').trim();

if (!result.match(/^\s*-/m) && !result.includes('\n-')) {
  result = 'NONE';
}

return [{ json: { ...input, text: result } }];

// Котировки Brent и TTF газ
const headers = { 'User-Agent': 'Mozilla/5.0' };
let brent = { current: null, prevDay: null, march1: null };
let ttf = { current: null, prevDay: null, march1: null };

const march1ts = new Date('2026-03-01T00:00:00Z').getTime() / 1000;

// Ищем ближайшую цену к дате
const findClosest = (timestamps, closes, targetTs) => {
  let best = null;
  let bestDiff = Infinity;
  for (let i = 0; i < timestamps.length; i++) {
    if (closes[i] === null) continue;
    const diff = Math.abs(timestamps[i] - targetTs);
    if (diff < bestDiff) { bestDiff = diff; best = closes[i]; }
  }
  return best;
};

try {
  const bResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://query1.finance.yahoo.com/v8/finance/chart/BZ=F?interval=1d&range=1mo',
    headers, json: true,
  });
  const r = bResp.chart.result[0];
  const ts = r.timestamp || [];
  const cl = r.indicators.quote[0].close || [];
  const valid = cl.filter(c => c !== null);
  brent.current = valid[valid.length - 1];
  brent.prevDay = valid.length >= 2 ? valid[valid.length - 2] : null;
  brent.march1 = findClosest(ts, cl, march1ts);
} catch(e) {}

try {
  const tResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://query1.finance.yahoo.com/v8/finance/chart/TTF=F?interval=1d&range=1mo',
    headers, json: true,
  });
  const r = tResp.chart.result[0];
  const ts = r.timestamp || [];
  const cl = r.indicators.quote[0].close || [];
  const valid = cl.filter(c => c !== null);
  ttf.current = valid[valid.length - 1];
  ttf.prevDay = valid.length >= 2 ? valid[valid.length - 2] : null;
  ttf.march1 = findClosest(ts, cl, march1ts);
} catch(e) {}

// Предыдущие котировки из Redis
let prevBrent = null;
let prevTtf = null;
try {
  const rd = $('Redis: Пред. котировки').first().json;
  const raw = rd.propertyName || rd.value || '';
  if (raw) {
    const p = JSON.parse(raw);
    prevBrent = p.brent || null;
    prevTtf = p.ttf || null;
  }
} catch(e) {}

const fmt = (v) => v !== null ? Number(v).toFixed(2) : '—';
const pct = (cur, prev) => {
  if (!cur || !prev) return null;
  return ((cur - prev) / prev * 100).toFixed(1);
};
const tag = (val) => {
  if (val === null) return '';
  const n = parseFloat(val);
  const arrow = n >= 0 ? '📈' : '📉';
  const sign = n >= 0 ? '+' : '';
  return arrow + sign + val + '%';
};

// Формируем строки
const brentParts = ['🛢 Brent: <b>$' + fmt(brent.current) + '</b>'];
const bDay = pct(brent.current, brent.prevDay);
if (bDay !== null) brentParts.push(tag(bDay) + ' за день');
const bMar = pct(brent.current, brent.march1);
if (bMar !== null) brentParts.push(tag(bMar) + ' с 1 мар');

const ttfParts = ['🔥 Газ TTF: <b>€' + fmt(ttf.current) + '</b>'];
const tDay = pct(ttf.current, ttf.prevDay);
if (tDay !== null) ttfParts.push(tag(tDay) + ' за день');
const tMar = pct(ttf.current, ttf.march1);
if (tMar !== null) ttfParts.push(tag(tMar) + ' с 1 мар');

const block = '\n\n📊 <b>Котировки:</b>\n' + brentParts.join(' | ') + '\n' + ttfParts.join(' | ');

// Для промпта LLM — чистый текст без HTML
const promptLine = 'Brent: $' + fmt(brent.current) +
  (bMar !== null ? ' (' + (parseFloat(bMar) >= 0 ? '+' : '') + bMar + '% с 1 марта)' : '') +
  ', газ TTF: €' + fmt(ttf.current) +
  (tMar !== null ? ' (' + (parseFloat(tMar) >= 0 ? '+' : '') + tMar + '% с 1 марта)' : '');

return [{ json: {
  quotesBlock: block,
  quotesPromptLine: promptLine,
  brentCurrent: brent.current,
  ttfCurrent: ttf.current,
} }];

const input = $input.first().json;
let text = input.text || '';

let refMap = {};
try {
  const raw = $('Сборка в текст').first().json.refMap || '{}';
  refMap = JSON.parse(raw);
} catch(e) {}

// Заменяем [N] на ссылку. Если номер не найден в refMap — убираем [N] полностью.
text = text.replace(/\[(\d+)\]/g, (match, num) => {
  const ref = refMap[num];
  if (ref && ref.url) {
    return '(<a href="' + ref.url + '">' + ref.source + '</a>)';
  }
  // Номер не найден в refMap — LLM галлюцинация, убираем тег
  return '';
});

// Чистим двойные пробелы которые могут остаться после удаления [N]
text = text.replace(/  +/g, ' ').trim();

return [{ json: { ...input, text } }];

const raw = $input.first().json.propertyName;
const prev = (raw && !isNaN(parseInt(raw))) ? parseInt(raw) : 0;
const current = prev + 1;
const shouldPromo = current % 3 === 0;

let promoText = '';
if (shouldPromo) {
  const cycle = current / 3; // 1, 2, 3, 4...

  if (cycle === 1) {
    promoText = 'Кстати, я пишу о том, как сделать подобных ботов. '
      + 'Буду рад подписке - @aborisov_pro';
  } else if (cycle === 2) {
    promoText = 'Напоминаю, у меня есть канал для тех, кто хочет '
      + 'делать подобных ботов - @aborisov_pro';
  } else {
    promoText = 'Канал автора бота - @aborisov_pro';
  }
}

return [{ json: { counter: current, shouldPromo, promoText } }];

const FEEDS = [
  // === Иран / регион — прямое покрытие ===
  { label: '🇮🇷 Pars Today',           url: 'https://parstoday.ir/en/rss' },
  { label: '🇮🇷 Tehran Times',         url: 'https://www.tehrantimes.com/rss' },
  { label: '🇵🇸 Middle East Monitor',  url: 'https://www.middleeastmonitor.com/feed/' },
  { label: '🇦🇪 Arabian Post',         url: 'https://thearabianpost.com/feed/' },
  { label: '🇸🇦 Asharq Al-Awsat',      url: 'https://english.aawsat.com/feed' },
  { label: '🇸🇦 Arab News',            url: 'https://www.arabnews.com/rss.xml' },
  { label: '🇶🇦 Al Jazeera',           url: 'https://www.aljazeera.com/xml/rss/all.xml' },

  // === Wire-агентства (первоисточники) ===
  { label: '📡 Reuters',               url: 'https://feeds.reuters.com/reuters/topNews' },

  // === Западные СМИ — World-разделы ===
  { label: '🇬🇧 BBC World',            url: 'https://feeds.bbci.co.uk/news/world/rss.xml' },
  { label: '🇬🇧 Guardian World',       url: 'https://www.theguardian.com/world/rss' },
  { label: '🇺🇸 NYT US',              url: 'https://rss.nytimes.com/services/xml/rss/nyt/US.xml' },
  { label: '🇺🇸 WashPost',            url: 'https://feeds.washingtonpost.com/rss/national' },
  { label: '🇺🇸 NPR',                 url: 'https://feeds.npr.org/1003/rss.xml' },
  { label: '🇺🇸 ABC News',            url: 'https://abcnews.go.com/abcnews/usheadlines' },

  // === Нейтральные / незападные ===
