// === Collector-версия: без зависимости от Нормализация / Redis: Читать lastSeen ===
// Берём статьи за последние 3 часа (перекрываем 15-минутные запуски с запасом)

const httpItems = $input.all();
const feedItems = $('Список лент').all();

const now = Date.now();
const cutoffMs = now - 3 * 60 * 60 * 1000; // 3 часа назад

const GOOGLE_LABEL = '🔍 Google: Iran 24h';
const GOOGLE_LIMIT = 4;

const results = [];
const googleBuffer = [];
const seenUrls = new Set();
const seenTitleKeys = new Set();

const decodeHtml = (s = '') => s
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&nbsp;/g, ' ')
  .trim();

const stripTags = (s = '') => decodeHtml(String(s).replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();

const tagText = (content, tagNames) => {
  for (const tag of tagNames) {
    const safeTag = tag.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
    const re = new RegExp(`<${safeTag}[^>]*>([\\s\\S]*?)<\\/${safeTag}>`, 'i');
    const m = content.match(re);
    if (m && m[1]) {
      const cleaned = stripTags(m[1]);
      if (cleaned) return cleaned;
    }
  }
  return null;
};

const extractLink = (content) => {
  const atomAlt = content.match(/<link[^>]*\brel=["']alternate["'][^>]*\bhref=["']([^"']+)["']/i);
  if (atomAlt?.[1]) return atomAlt[1].trim();
  const atomAny = content.match(/<link[^>]*\bhref=["']([^"']+)["']/i);
  if (atomAny?.[1]) return atomAny[1].trim();
  const rssLink = tagText(content, ['link', 'guid', 'id']);
  if (rssLink && /^https?:\/\//i.test(rssLink)) return rssLink;
  return null;
};

const normalizeUrl = (url) => {
  try {
    const u = new URL(url);
    u.hash = '';
    const removeParams = [
      'utm_source','utm_medium','utm_campaign','utm_term','utm_content',
      'ocid','cmpid','guccounter','gaa_at','gaa_n','gaa_ts','s',
      'ns_mchannel','ns_campaign','ns_source','ns_linkname','ns_fee',
      'smid','fbclid','gclid','mc_cid','mc_eid'
    ];
    removeParams.forEach(p => u.searchParams.delete(p));
    let pathname = u.pathname.replace(/\/$/, '').replace(/\/amp$/, '').replace(/\/amp\//, '/');
    u.pathname = pathname || '/';
    return u.toString();
  } catch (e) {
    return String(url || '').trim();
  }
};

const titleKey = (title) => String(title || '')
  .toLowerCase()
  .replace(/[«»"'`]/g, '')
  .replace(/[^\p{L}\p{N}\s]/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 180);

for (let i = 0; i < httpItems.length; i++) {
  const item = httpItems[i];
  const xml = item.json?.data || item.json?.body || item.json || '';
  if (!xml || typeof xml !== 'string') continue;

  const label = feedItems[i]?.json?.label || 'Источник';
  const entryMatches = xml.matchAll(/<(?:item|entry)\b[\s\S]*?>[\s\S]*?<\/(?:item|entry)>/gi);

  for (const match of entryMatches) {
    const entryXml = match[0];
    const title = tagText(entryXml, ['title']);
    const linkRaw = extractLink(entryXml);
    const description = tagText(entryXml, ['description', 'summary', 'content', 'content:encoded']);
    if (!title || !linkRaw) continue;

    const link = normalizeUrl(linkRaw);
    const dateStr = tagText(entryXml, ['pubDate', 'published', 'updated', 'dc:date']);
    if (dateStr) {
      const pubTs = new Date(dateStr).getTime();
      if (!isNaN(pubTs) && pubTs < cutoffMs) continue;
    }

    const tKey = titleKey(title);
    if (seenUrls.has(link) || seenTitleKeys.has(tKey)) continue;
    seenUrls.add(link);
    seenTitleKeys.add(tKey);

    const articleObj = {
      title,
      link,
      source: label,
      description: description || ''
    };

    if (label === GOOGLE_LABEL) googleBuffer.push(articleObj);
    else results.push(articleObj);
  }
}

for (let k = googleBuffer.length - 1; k > 0; k--) {
  const j = Math.floor(Math.random() * (k + 1));
  [googleBuffer[k], googleBuffer[j]] = [googleBuffer[j], googleBuffer[k]];
}
googleBuffer.slice(0, GOOGLE_LIMIT).forEach(r => {
  const tKey = titleKey(r.title);
  if (!seenTitleKeys.has('google:' + tKey)) {
    seenTitleKeys.add('google:' + tKey);
    results.push(r);
  }
});

if (results.length === 0) {
  return [{ json: { isEmpty: true } }];
}

return results.map(r => ({ json: r }));

// Агрегируем новые статьи из потока в один массив
const items = $input.all();

const newArticles = items
  .filter(i => !i.json.isEmpty)
  .map(i => i.json);

return [{ json: { newArticles } }];

// Мержим новые статьи с существующим кэшем, дедуп по link + title
const newArticles = $('Агрегировать новые').first().json.newArticles || [];

let existing = [];
try {
  const raw = $input.first().json.cachedRaw || '';
  if (raw) {
    const parsed = JSON.parse(raw);
    existing = parsed.articles || [];
  }
} catch (e) {}

// --- Нормализация заголовка для дедупа ---
const titleKey = (title) => String(title || '')
  .toLowerCase()
  .replace(/[«»"'`''""]/g, '')
  .replace(/[^\p{L}\p{N}\s]/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 180);

// Дедуп: существующие + новые, проверяем И link, И titleKey
const seenLinks = new Set(existing.map(a => a.link));
const seenTitles = new Set(existing.map(a => titleKey(a.title)));

const toAdd = newArticles.filter(a => {
  const tKey = titleKey(a.title);
  if (seenLinks.has(a.link) || seenTitles.has(tKey)) return false;
  seenLinks.add(a.link);
  seenTitles.add(tKey);
  return true;
});

const merged = [...existing, ...toAdd];

if (merged.length === 0) {
  return [{ json: { skip: true } }];
}

return [{ json: {
  skip: false,
  value: JSON.stringify({
    articles: merged,
    updatedAt: Date.now(),
    count: merged.length,
    addedNow: toAdd.length
  }),
  count: merged.length,
  addedNow: toAdd.length
}}];

// Распаковываем кэш из Redis в поток items
// Дедуп по нормализованному заголовку — оставляем одну версию каждой новости
const chatId = String($('Нормализация').first().json.message.chat.id);

let articles = [];
try {
  const raw = $input.first().json.cachedRaw || '';
  if (raw) {
    const parsed = JSON.parse(raw);
    articles = parsed.articles || [];
  }
} catch(e) {}

if (articles.length === 0) {
  return [{ json: { isEmpty: true, redisKey: 'iran1:empty:placeholder' } }];
}

// --- Дедуп по заголовку: оставляем первую (самую старую) версию ---
const titleKey = (title) => String(title || '')
  .toLowerCase()
  .replace(/[«»"'`''""]/g, '')
  .replace(/[^\p{L}\p{N}\s]/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 180);

const seenTitles = new Set();
const unique = [];

for (const a of articles) {
  const tKey = titleKey(a.title);
  if (seenTitles.has(tKey)) continue;
  seenTitles.add(tKey);
  unique.push(a);
}

return unique.map(a => ({
  json: {
    ...a,
    chatId,
    redisKey: 'iran1:' + chatId + ':' + (a.link || '').replace(/[^a-zA-Z0-9]/g, '_').substring(0, 120)
  }
}));
